function validate(input) {
  const [{ employees = [], performance_reviews = [] }] = input;
  const staff = new Set(), names = new Set(), reviews = new Set(), days = new Set();
  for (const [id, name] of employees) {
    if (id === null || name === null) return 'employee_id and name cannot be null.';
    if (staff.has(id)) return `employee_id ${id} appears twice in employees.`;
    staff.add(id);
    const key = String(name).toLowerCase();
    if (names.has(key)) return `The name ${name} appears twice in employees.`;
    names.add(key);
  }
  for (const [id, employee, day, rating] of performance_reviews) {
    if ([id, employee, day, rating].includes(null)) return 'No value in performance_reviews may be null.';
    if (reviews.has(id)) return `review_id ${id} appears twice in performance_reviews.`;
    reviews.add(id);
    if (!staff.has(employee)) return `employee_id ${employee} is not in employees.`;
    if (days.has(`${employee}|${day}`)) return `Employee ${employee} has two reviews on ${day}.`;
    days.add(`${employee}|${day}`);
    if (!Number.isInteger(rating) || rating < 1 || rating > 5) return 'rating must be an integer from 1 to 5.';
  }
  return null;
}

