function generate(rand, size) {
  const small = size === 'small';
  const int = n => Math.floor(rand() * n);
  const pad = n => String(n).padStart(2, '0');
  const first = ['Alice', 'Bob', 'Carol', 'David', 'Emma', 'Frank', 'Grace', 'Henry', 'Ivy', 'Jack', 'Kara', 'Liam', 'Mia', 'Noah', 'Olga', 'Paul', 'Quinn', 'Rosa', 'Sam', 'Tara'];
  const last = ['Johnson', 'Smith', 'Davis', 'Wilson', 'Brown', 'Lee', 'Kim', 'Patel', 'Garcia', 'Chen', 'Novak', 'Silva', 'Moreau', 'Rossi', 'Haas', 'Berg', 'Ito', 'Okafor', 'Diaz', 'Young'];
  const offset = int(400);
  const count = small ? int(6) : 300, cap = small ? 8 : 2000;
  const employees = [], reviews = [];
  for (let id = 1; id <= count; id++) {
    const k = (offset + id) % 400;
    employees.push([id, `${first[k % 20]} ${last[Math.floor(k / 20)]}`]);
    // Distinct (year, month) slots keep each employee's review dates distinct.
    const slots = [];
    for (let s = 0; s < 36; s++) slots.push(s);
    for (let i = slots.length - 1; i > 0; i--) { const j = int(i + 1); [slots[i], slots[j]] = [slots[j], slots[i]]; }
    const n = int(small ? 5 : 8), picked = slots.slice(0, n).sort((a, b) => a - b);
    // Half the employees end on a strictly rising run of three; the rest get random ratings.
    const rising = rand() < 0.5;
    const top = [1, 2, 3, 4, 5].sort(() => rand() - 0.5).slice(0, 3).sort((a, b) => a - b);
    picked.forEach((slot, i) => {
      const fromEnd = n - 1 - i;
      const rating = rising && fromEnd < 3 ? top[2 - fromEnd] : 1 + int(5);
      reviews.push([id, `${2022 + Math.floor(slot / 12)}-${pad(slot % 12 + 1)}-${pad(1 + int(28))}`, rating]);
    });
  }
  for (let i = reviews.length - 1; i > 0; i--) { const j = int(i + 1); [reviews[i], reviews[j]] = [reviews[j], reviews[i]]; }
  const performance_reviews = reviews.slice(0, cap).map((review, i) => [i + 1, ...review]);
  return [{ employees, performance_reviews }];
}
